/**
 * Returns { center: [lat, lon], zoom } for a country, or null if not found.
 */
export function getCountryCenter(countryName) {
  const entry = findByNormalizedKey(COUNTRY_COORDS, countryName)
  if (!entry) return null
  return { center: [entry.lat, entry.lon], zoom: entry.zoom || 5.5 }
}

/**
 * Returns { center: [lat, lon], zoom } for an Indian state, or null if not found.
 */
export function getStateCenter(stateName) {
  const entry = findByNormalizedKey(STATE_COORDS, stateName)
  if (!entry) return null
  return { center: [entry.lat, entry.lon], zoom: entry.zoom || 7 }
}

/**
 * Returns { center: [lat, lon], zoom } for a Tamil Nadu district, or null if not found.
 */
export function getDistrictCenter(districtName) {
  const entry = findByNormalizedKey(TN_DISTRICT_COORDS, districtName)
  if (!entry) return null
  return { center: [entry.lat, entry.lon], zoom: 10.5 }
}

/**
 * Returns { center: [lat, lon], zoom } for a taluk within a district, or null if not found.
 */
export function getTalukCenter(districtName, talukName) {
  const distEntry = findByNormalizedKey(TN_TALUK_COORDS, districtName)
  if (distEntry) {
    const talukEntry = findByNormalizedKey(distEntry, talukName)
    if (talukEntry) {
      return { center: [talukEntry.lat, talukEntry.lon], zoom: 13 }
    }
  }
  const normTaluk = normalizeKey(talukName)
  for (const taluks of Object.values(TN_TALUK_COORDS)) {
    for (const [k, v] of Object.entries(taluks)) {
      if (normalizeKey(k) === normTaluk) {
        return { center: [v.lat, v.lon], zoom: 13 }
      }
    }
  }
  return null
}
